const now = Date.now();
const isExpired = cachedEntry && now - cachedEntry.lastFetched > cachedEntry.ttl;
const columnConfigProvided = columnConfig;

if (cachedEntry && !isExpired && this.getCachedEntityValue && (!query || (!query.includes("body") && getActivityType(query)))) {
  return Promise.resolve(this.getCachedEntityValue(entity, "entities"));
} else {
  const options = {
    page: page,
    limit: limit,
    query: query,
    apiType: apiType,
    customEntityKey: customEntityKey
  };

  // 1. 'await' the response from the data service
  const { entities, total, totalFiltered, pageCount, hasNextPage } = await this.dataService.getData(entity, options);

  // 2. Build the cache entry with the new data
  const cacheEntry = {
    entities: entities,
    total: total,
    totalFiltered: totalFiltered,
    pageCount: pageCount,
    hasNextPage: hasNextPage,
    lastFetched: now,
    ttl: TTL
  };

  if (columnConfigProvided) {
    cacheEntry.columns = this.dataService.processData.generateColumnDefinitions(columnConfig.columnNames, columnConfig.options);
  }

  // 3. Determine the correct cache key and store the entry
  let cacheKey = entity;
  if (query) {
    cacheKey = insertActivityType(entity, getActivityType(query));
  }
  this.cacheStorage[cacheKey] = cacheEntry;

  // 4. Return the full response object for the caller to use
  return { entities, total, totalFiltered, pageCount, hasNextPage };
}

function getActivityType(query) {
  const parts = query.split('&');
  for (const part of parts) {
    const [key, value] = part.split('=');
    if (key === "activityType") {
      return value;
    }
  }
  return null;
}

function insertActivityType(originalPath, activityType) {
  const parts = originalPath.split('/');

  if (parts.length >= 3 && parts[0] === "activity") {
    const newParts = [parts[0], activityType, ...parts.slice(1)];
    return newParts.join('/');
  } else {
    return originalPath;
  }
}

